/// <summary>
/// Continuing permission notice report controller
/// Class <c>METContinuingPermissionNoticeController</c> controller
/// </summary>
class METContinuingPermissionNoticeController extends SrsReportRunController
{
}

Method.Source:
/// <summary>
/// constructor
/// </summary>
/// <returns>constructor</returns>
public static METContinuingPermissionNoticeController construct()
{
    return new METContinuingPermissionNoticeController();
}

    // ** WIP, continuing permission notice requirements tbd.
    // Report may end up being generated externally.

    /// <summary>
    /// Main method to run report
    /// </summary>
    /// <param name = "_args">_args</param>
    static void main(Args _args)
    {
        METContinuingPermissionNoticeController controller =
            METContinuingPermissionNoticeController::construct();

        controller.parmReportName(ssrsReportStr(METContinuingPermissionNotice, CPNReport));
        controller.parmArgs(_args);
        controller.parmDialogCaption("@MET:METCPNotice");
        controller.startOperation();
    }

    /// <summary>
    /// pre prompt modify contract
    /// </summary>
    protected void prePromptModifyContract()
    {
        METContinuingPermissionNoticeContract contract = this.parmReportContract().parmRdpContract();
 
        contract.parmshipmentId(args.record().RecId);
 
        // Set the report design name.
        this.parmReportContract().parmReportName(ssrsReportStr(METContinuingPermissionNotice, CPNReport));
        this.parmReportContract().parmPrintSettings().printMediumType(SRSPrintMediumType::Screen);

        this.parmShowDialog(false);
    }
